    const ForEachClosure: TForEachRecordClosure);
end;
_ = HigherOrder; // atalho — mesma classe, nome curto
OBJECT PASCAL · FILTRAR, MAPEAR E SOMAR SEM LOOPS MANUAIS
LEmEstoque := _.Filter<TProduto>(LProdutos.ToArray,
  function(const P: TProduto): Boolean
  begin
    Result := P.qtestoque > 0;
  end);
LTotalEstoque := _.Reduce<Integer>(
  _.Map<TProduto, Integer>(LEmEstoque,
    function(const P: TProduto): Integer
    begin
      Result := P.qtestoque;
    end),
  function(const Left, Right: Integer): Integer
  begin
    Result := Left + Right;
  end, 0);
// direto sobre um TDataSet — combina bem com SelectDataSet (Capítulo 9, seção 9.9)
_.ForEachRecord(LDataSet,
  procedure(const Item: TDataset)
  begin
    WriteLn(Item.FieldByName('dsproduto').AsString);
  end);




Nada aqui substitui um for comum — é conveniência para quem prefere estilo funcional em transformações
curtas e encadeadas. Para coleções grandes ou hot path de performance, um loop explícito continua sendo a opção
mais previsível.
23.11Avaliador de expressões: IExprEvaluator
O {{if price * qty * (1 - discount) > 100}} do TemplatePro (Capítulo 19) e as expressões dentro de um
.env (Capítulo 26) são resolvidos pela mesma biblioteca por baixo dos panos: ExprEvaluator.pas, vendorizada
dentro do DMVC. Nada impede usá-la diretamente, fora de template ou .env — por exemplo, para uma regra de
negócio configurável em texto (uma fórmula de desconto guardada no banco, editável sem recompilar):
OBJECT PASCAL · IEXPREVALUATOR
IExprEvaluator = interface
  procedure RegisterFunction(const Name: string; Handler: TFuncHandler);
  function Evaluate(const Expr: string): Variant;
  procedure SetVar(const Name: string; Value: Variant);
  function GetVar(const Name: string): Variant;
  function VariantToString(const Value: Variant): string;
  procedure SetOnResolveExternalVariable(const Resolver: TExternalVariableResolver);
end;
TExprEvaluator = class(TInterfacedObject, IExprEvaluator)
public
  constructor Create;
end;
TFuncHandler = reference to function(const Args: array of Variant): Variant;
OBJECT PASCAL · FÓRMULA DE DESCONTO CONFIGURÁVEL, VINDA DO BANCO
var
  LEval: IExprEvaluator;
  LValorFinal: Currency;
begin
  LEval := TExprEvaluator.Create;
  LEval.SetVar('preco', LItem.vlunitario);
  LEval.SetVar('qtd', LItem.qtitem);
  LEval.RegisterFunction('arredonda',
    function(const Args: array of Variant): Variant
    begin
      Result := RoundTo(Args[0], -2);
    end);
  // fórmula vinda de uma coluna de configuração, não hardcoded no fonte
  LValorFinal := LEval.Evaluate('arredonda(preco * qtd * 0.9)'); // 10% de desconto
end;




