25.3Exemplo completo: feature flag por tenant
O Capítulo 4 já mostrou um middleware de infraestrutura (request ID + duração). Aqui vai um de negócio —
desligar uma funcionalidade inteira para tenants específicos sem precisar de deploy, um padrão comum em
sistemas SaaS multiempresa (multi-tenant). A decisão de fase importa: o flag é por rota (controller + action), então a
checagem só faz sentido depois que o roteamento já resolveu qual action seria chamada — ou seja, em
OnBeforeControllerAction, não em OnBeforeRouting:




OBJECT PASCAL · MIDDLEWARE DE FEATURE FLAG POR TENANT (EXEMPLO DIDÁTICO COMPLETO)
unit App.Middleware.FeatureFlag;
interface
uses
  MVCFramework, MVCFramework.Commons;
type
  // Contrato mínimo para o middleware não depender de Redis diretamente —
  // facilita trocar a implementação (Redis, memória, banco) e testar com um mock.
  IFeatureFlagStore = interface
    ['{B2E1F6A1-3B0A-4E7B-9C34-2B6F4B0B0A11}']
    function IsEnabled(const ATenantId: Integer; const AFeatureKey: string): Boolean;
  end;
  TFeatureFlagMiddleware = class(TInterfacedObject, IMVCMiddleware)
  private
    FStore: IFeatureFlagStore;
    // Mapa fixo action -> chave de feature; em produção isso poderia vir de
    // um atributo customizado no método do controller, mas um dicionário
    // simples já ilustra o mecanismo sem precisar de mais RTTI.
    function FeatureKeyFor(const AControllerQualifiedClassName, AActionName: string): string;
    function GetTenantId(AContext: TWebContext): Integer;
  public
    constructor Create(const AStore: IFeatureFlagStore);
    procedure OnBeforeRouting(AContext: TWebContext; var AHandled: Boolean);
    procedure OnBeforeControllerAction(AContext: TWebContext;
      const AControllerQualifiedClassName: string; const AActionName: string;
      var AHandled: Boolean);
    procedure OnAfterControllerAction(AContext: TWebContext;
      const AControllerQualifiedClassName: string; const AActionName: string;
      const AHandled: Boolean);
    procedure OnAfterRouting(AContext: TWebContext; const AHandled: Boolean);
  end;
implementation
uses
  System.SysUtils;
const
  // action "qualificada" -> chave de feature flag. Vazio = sem flag, sempre libera.
  FEATURE_MAP: array[0..1] of array[0..1] of string = (
    ('TPedidoController.EnviarConfirmacaoEmail', 'pedido_confirmacao_email_v2'),
    ('TClienteController.ExportarCsv',            'cliente_exportacao_csv')
  );




