  protected
    procedure OnAfterLoad; override;
    procedure OnAfterInsertOrUpdate; override;
  public
    constructor Create; override;
    destructor Destroy; override;
    property cdpedido: NullableInt64 read Fcdpedido write Fcdpedido;
    property cdcliente: Integer read Fcdcliente write Fcdcliente;
    property dtpedido: TDateTime read Fdtpedido write Fdtpedido;
    property vltotal: Currency read Fvltotal write Fvltotal;
    property stpedido: SmallInt read Fstpedido write Fstpedido;
