{ TPedido }
constructor TPedido.Create;
begin




  inherited Create;
  Fitens := TObjectList<TPedidoItem>.Create(True);
end;
destructor TPedido.Destroy;
begin
  Fitens.Free;
  inherited Destroy;
end;
procedure TPedido.OnAfterLoad;
begin
  inherited;
  Fitens.Free;
  Fitens := TMVCActiveRecord.SelectRQL<TPedidoItem>(
    Format('eq(cdpedido,%d)', [cdpedido.Value]), 200);
end;
procedure TPedido.OnAfterInsertOrUpdate;
var
  LItensNoBanco: TObjectList<TPedidoItem>;
  LItem: TPedidoItem;
begin
  inherited;
  // itens novos ainda chegam sem cdpedido preenchido (pedido acabou de ganhar PK no Insert)
  for LItem in Fitens do
    LItem.cdpedido := cdpedido.Value;
  LItensNoBanco := TMVCActiveRecord.SelectRQL<TPedidoItem>(
    Format('eq(cdpedido,%d)', [cdpedido.Value]), 200);
  try
    TMVCActiveRecord.Merge<TPedidoItem>(LItensNoBanco, Fitens,
      [mmInsert, mmUpdate, mmDelete]).Apply;
  finally
    LItensNoBanco.Free;
  end;
end;
end.
