OBJECT PASCAL · LOJAAPI.SEED.PAS
unit LojaAPI.Seed;
interface
procedure SeedInicial;
implementation
uses
  System.Generics.Collections, MVCFramework.ActiveRecord,
  LojaAPI.Model.Entity.Produto, LojaAPI.Model.Entity.Cliente;
procedure SeedInicial;
var
  LJaTemDados: TObjectList<TProduto>;
  LProduto: TProduto;
  LCliente: TCliente;
begin
  LJaTemDados := TMVCActiveRecord.SelectRQL<TProduto>('limit(1,0)', 1);
  try
    if LJaTemDados.Count > 0 then
      Exit; // seed já aplicado nesta base — não duplica
  finally
    LJaTemDados.Free;
  end;
  TMVCActiveRecord.CurrentConnection.StartTransaction;
  try
    LProduto := TProduto.Create;
    try
      LProduto.dsproduto := 'Teclado mecânico';
      LProduto.vlpreco := 249.90;
      LProduto.qtestoque := 50;
      LProduto.Insert;
    finally
      LProduto.Free;
    end;
    LProduto := TProduto.Create;
    try
      LProduto.dsproduto := 'Mouse sem fio';
      LProduto.vlpreco := 89.90;
      LProduto.qtestoque := 120;
      LProduto.Insert;
    finally
      LProduto.Free;
    end;




