      LProduto.dsproduto := 'Monitor 24" Full HD';
      LProduto.vlpreco := 799.00;
      LProduto.qtestoque := 15;
      LProduto.Insert;
    finally
      LProduto.Free;
    end;
    LCliente := TCliente.Create;
    try
      LCliente.dsnome := 'Cliente de Teste';
      LCliente.dsemail := 'teste@lojaapi.com.br';
      // placeholder — o hash BCrypt de verdade entra no Capítulo 30
      LCliente.pwsenha_hash := '$2a$12$examplehashonlyfortutorialpurposexx';
      LCliente.Insert;
    finally
      LCliente.Free;
    end;
    TMVCActiveRecord.CurrentConnection.Commit;
  except
    TMVCActiveRecord.CurrentConnection.Rollback;
    raise;
  end;
end;
end.
ATENÇÃO
A checagem de "já tem dados" olha só a tabela produto. Isso é suficiente para o propósito deste seed
(evitar duplicar as mesmas três linhas a cada restart), mas não é uma migration versionada de verdade —
para controle de schema com histórico e rollback, a abordagem correta em projetos reais é uma ferramenta
de migration dedicada ou, no mínimo, scripts numerados sob controle de versão, um por alteração de
schema. O sql/lojadb_schema.sql da seção 29.2 cobre a criação inicial; evoluções de schema depois disso
merecem seu próprio arquivo, não uma edição retroativa do script original.
⚠




TEntidadeBase do Capítulo 9 reaproveitada como base comum das quatro entidades — auditoria
automática sem nenhuma linha extra em controller.
TProduto e TCliente mapeadas com PK NullableInt64 autogerada; pwsenha_hash protegida com
[MVCDoNotSerialize] (Capítulo 13).
TPedido + TPedidoItem como master-detail: [MVCOwned(TPedidoItem)] na lista itens, OnAfterLoad
carregando os filhos por SelectRQL, OnAfterInsertOrUpdate sincronizando via
TMVCActiveRecord.Merge<T> — a mesma receita da seção 9.7, agora aplicada ao domínio real.
Seed inicial idempotente (checa antes de inserir) criando três produtos e um cliente de teste dentro de uma
transação explícita.
Com as quatro tabelas criadas, as entidades mapeadas e um cliente de teste já no banco, o próximo capítulo fecha o
ciclo de identidade: login do TCliente por dsemail/senha, hash real com BCrypt no lugar do placeholder desta
seção 29.7, e o middleware JWT protegendo os endpoints de pedido que o Capítulo 31 vai construir em cima do
master-detail que acabamos de mapear.

capitulos.texto:
PARTE X — PROJETO FINAL
Capítulo 31
Endpoints CRUD Completos com RQL, Paginação e
Validação
As entidades da Loja API já existem (TProduto, TCliente, TPedido/TPedidoItem, capítulos 28-29) e a
autenticação JWT já protege a API (capítulo 30). Falta a parte que transforma esse esqueleto em uma API de verdade: os
controllers de negócio. Este capítulo constrói TProdutoController por completo — listagem paginada com filtro
opcional, busca avançada em RQL cru, detalhe, criação com validação, atualização e exclusão — e depois
TPedidoController.CreatePedido, o endpoint mais denso do projeto: recebe um pedido com seus itens já no corpo
(master-detail), valida estoque, calcula o total, persiste tudo numa transação e dá baixa no estoque de cada produto
envolvido. Nenhuma técnica aqui é nova — é a aplicação, em conjunto, do que os capítulos 3 (roteamento e respostas
tipadas), 9 (ActiveRecord, master-detail, transações) e 10 (RQL) já estabeleceram isoladamente.
31.1Visão geral: rotas e responsabilidades
Como todo controller protegido da Loja API, TProdutoController leva [MVCRequiresAuthentication] na classe
— o middleware JWT do capítulo 30 barra qualquer requisição sem token válido antes de qualquer ação rodar. A
tabela a seguir resume o que este capítulo implementa; o corpo de cada método vem nas seções seguintes.
Endpoints de TProdutoController (unit LojaAPI.Controller.Produto.pas)
VerboRotaAçãoRespostas possíveis
GET/produtosGetProdutos200
GET/produtos/searchesGetProdutosSearch200, 400
GET/produtos/($id)GetProdutoById200, 404
POST/produtosCreateProduto201, 400
PUT/produtos/($id)UpdateProduto200, 400, 404
DELETE/produtos/($id)DeleteProduto204, 404




OBJECT PASCAL · LOJAAPI.CONTROLLER.PRODUTO.PAS — INTERFACE COMPLETA
[MVCPath('/produtos')]
[MVCRequiresAuthentication]
TProdutoController = class(TMVCController)
private
  function MontaRQLDoFiltro(const AFilter: string): string;
public
  [MVCPath]
  [MVCHTTPMethod([httpGET])]
  procedure GetProdutos(
    [MVCFromQueryString('page', '1')] APage: Integer;
    [MVCFromQueryString('limit', '20')] ALimit: Integer;
    [MVCFromQueryString('filter', '')] AFilter: string);
  [MVCPath('/searches')]
  [MVCHTTPMethod([httpGET])]
  procedure GetProdutosSearch(
    [MVCFromQueryString('rql', '')] ARql: string;
    [MVCFromQueryString('limit', '50')] ALimit: Integer);
  [MVCPath('/($id)')]
  [MVCHTTPMethod([httpGET])]
  procedure GetProdutoById(const id: Integer);
  [MVCPath]
  [MVCHTTPMethod([httpPOST])]
  [MVCConsumes(TMVCMediaType.APPLICATION_JSON)]
  procedure CreateProduto([MVCFromBody] AProduto: TProduto);
  [MVCPath('/($id)')]
  [MVCHTTPMethod([httpPUT])]
  [MVCConsumes(TMVCMediaType.APPLICATION_JSON)]
  procedure UpdateProduto(const id: Integer; [MVCFromBody] AProduto: TProduto);
  [MVCPath('/($id)')]
  [MVCHTTPMethod([httpDELETE])]
  procedure DeleteProduto(const id: Integer);
end;
ATENÇÃO
/produtos/searches e /produtos/($id) competem pelo mesmo verbo GET num segmento de mesma
posição — para o roteador, searches é, sintaticamente, um valor possível de id. Declare a rota literal
(/searches) antes da rota parametrizada na classe, como no bloco acima, e teste manualmente GET
/produtos/searches depois de qualquer alteração de rotas — se ela cair em GetProdutoById por engano,
a conversão de 'searches' para Integer falha e o cliente recebe um erro de parâmetro em vez do
resultado da busca. Esse é um cuidado de organização de rotas, não algo que o RQL ou o roteamento
resolvam sozinhos.
⚠




31.2Listagem paginada com filtro RQL opcional — GetProdutos
A assinatura segue a recomendação do capítulo 3 (seção 3.3): três parâmetros injetados via [MVCFromQueryString]
com valor default, no mesmo formato usado em /clientes e /pedidos. O parâmetro filter reaproveita o
formato campo|op|valor apresentado na seção 10.6 — aqui adaptado para os campos de TProduto (dsproduto,
vlpreco, qtestoque, cdcategoria) e restrito aos operadores com equivalente direto na gramática RQL (eq,
neq, gt/gte/lt/lte).




OBJECT PASCAL · MONTARQLDOFILTRO — VARIANTE DA SEÇÃO 10.6 PARA TPRODUTO
function TProdutoController.MontaRQLDoFiltro(const AFilter: string): string;
const
  // campo|op|valor -> operador(campo,valor); só os operadores com 1:1 direto em RQL
  MAPA_OPERADORES: array[0..5] of array[0..1] of string = (
    ('eq', 'eq'), ('neq', 'ne'), ('gt', 'gt'), ('gte', 'ge'), ('lt', 'lt'), ('lte', 'le'));
var
  LPar, LCampo, LOperador, LValor, LOpRql: string;
  LPartes: TArray<string>;
  LCondicoes: TStringList;
  i: Integer;
begin
  if AFilter.Trim.IsEmpty then
    Exit('');
  LCondicoes := TStringList.Create;
  try
    for LPar in AFilter.Split([';']) do
    begin
      LPartes := LPar.Split(['|']);
      if Length(LPartes) <> 3 then
        Continue;
      LCampo    := LPartes[0];
      LOperador := LPartes[1];
      LValor    := LPartes[2];
      LOpRql := '';
      for i := Low(MAPA_OPERADORES) to High(MAPA_OPERADORES) do
        if MAPA_OPERADORES[i][0] = LOperador then
        begin
          LOpRql := MAPA_OPERADORES[i][1];
          Break;
        end;
      if LOpRql = '' then
        Continue; // like/between/null ficam fora do escopo deste endpoint (vide seção 10.6)
      LCondicoes.Add(Format('%s(%s,%s)', [LOpRql, LCampo, LValor]));
    end;
    if LCondicoes.Count = 0 then
      Result := ''
    else
      Result := Format('and(%s)', [String.Join(',', LCondicoes.ToStringArray)]);
  finally
    LCondicoes.Free;




  end;
end;
OBJECT PASCAL · GETPRODUTOS — PAGINAÇÃO + COUNT<T> + SELECTRQL<T>
procedure TProdutoController.GetProdutos(APage, ALimit: Integer; AFilter: string);
var
  LFiltroRql, LConsultaRql: string;
  LProdutos: TObjectList<TProduto>;
  LTotal: Int64;
begin
  if APage < 1 then
    APage := 1;
  if (ALimit < 1) or (ALimit > 100) then
    ALimit := 20;
  LFiltroRql := MontaRQLDoFiltro(AFilter);
  // Count<T> recebe só o filtro (sem sort/limit) — é o substituto do count() que a
  // gramática RQL não tem (seção 10.2)
  LTotal := TMVCActiveRecord.Count<TProduto>(LFiltroRql);
  if LFiltroRql.IsEmpty then
    LConsultaRql := Format('sort(+dsproduto)&limit(%d,%d)', [ALimit, (APage - 1) * ALimit])
  else
    LConsultaRql := LFiltroRql + Format('&sort(+dsproduto)&limit(%d,%d)', [ALimit, (APage - 1) * 
ALimit]);
  LProdutos := TMVCActiveRecord.SelectRQL<TProduto>(LConsultaRql, ALimit);
  try
    Context.Response.SetCustomHeader('X-Total-Count', IntToStr(LTotal));
    Context.Response.SetCustomHeader('X-Page', IntToStr(APage));
    Context.Response.SetCustomHeader('X-Limit', IntToStr(ALimit));
    Render(OKResponse(LProdutos));
  finally
    LProdutos.Free;
  end;
end;
DICA
Os metadados de paginação saíram como headers (X-Total-Count, X-Page, X-Limit) —
Context.Response.SetCustomHeader já apareceu em middlewares (capítulo 6) e em respostas de controller
com HTMX (capítulo 20), então é código já verificado, sem inventar wrapper novo. Se preferir os metadados
dentro do próprio corpo JSON em vez de headers, a alternativa é montar a resposta com
ObjectDict().Add('data', LProdutos) (capítulos 12 e 14) e acrescentar uma segunda chave com um
objeto de metadados — as duas abordagens resolvem o mesmo problema, escolha uma e mantenha
consistente em toda a API.





31.3Busca avançada: RQL cru em GET /produtos/searches
GetProdutos cobre o caso comum (filtros simples vindos de uma grade de tela). Para consultas que a tradução
campo|op|valor não alcança — combinações de and/or aninhadas, in/out com lista de valores — o
endpoint abaixo aceita o texto RQL já pronto e o repassa direto para SelectRQL<TProduto>, exatamente como
descrito na seção 10.4.
Repare que SelectRQL<T> exige MaxRecordCount (seção 10.4) — não existe consulta RQL sem teto de linhas,
mesmo neste endpoint de "poder total" que aceita texto arbitrário do cliente.
31.4Detalhe e criação com validação
GetProdutoById é o mesmo padrão do capítulo 3: GetByPK<T> com RaiseExceptionIfNotFound = False,
checagem explícita de Assigned, NotFoundResponse se não existir. CreateProduto acrescenta a validação de
negócio pedida para este capítulo — dsproduto não pode ser vazio e vlpreco precisa ser maior que zero —
antes de qualquer chamada a Insert.
OBJECT PASCAL · GETPRODUTOSSEARCH
procedure TProdutoController.GetProdutosSearch(ARql: string; ALimit: Integer);
var
  LProdutos: TObjectList<TProduto>;
begin
  if ARql.Trim.IsEmpty then
  begin
    Render(BadRequestResponse('Parâmetro rql é obrigatório'));
    Exit;
  end;
  if (ALimit < 1) or (ALimit > 200) then
    ALimit := 50;
  LProdutos := TMVCActiveRecord.SelectRQL<TProduto>(ARql, ALimit);
  try
    Render(OKResponse(LProdutos));
  finally
    LProdutos.Free;
  end;
end;
// exemplo de chamada:
// GET /produtos/searches?rql=and(gt(vlpreco,100),lt(qtestoque,10))&limit=30
// GET /produtos/searches?rql=in(cdcategoria,(1,3,7))




31.5Atualização e exclusão
UpdateProduto repete a validação de CreateProduto — regra de negócio duplicada entre os dois métodos não é
elegante, mas é explícita, e é o padrão mais simples de acompanhar antes de introduzir uma camada de validação
compartilhada (fora do escopo deste capítulo). Carrega o registro existente, aplica os campos recebidos, chama
Update. DeleteProduto segue o mesmo carregamento e devolve 204 sem corpo.
OBJECT PASCAL · GETPRODUTOBYID E CREATEPRODUTO
procedure TProdutoController.GetProdutoById(const id: Integer);
var
  LProduto: TProduto;
begin
  LProduto := TMVCActiveRecord.GetByPK<TProduto>(id, False);
  try
    if not Assigned(LProduto) then
      Render(NotFoundResponse('Produto não encontrado'))
    else
      Render(OKResponse(LProduto));
  finally
    LProduto.Free;
  end;
end;
procedure TProdutoController.CreateProduto(AProduto: TProduto);
begin
  if AProduto.dsproduto.Trim.IsEmpty then
  begin
    Render(BadRequestResponse('dsproduto é obrigatório'));
    Exit;
  end;
  if AProduto.vlpreco <= 0 then
  begin
    Render(BadRequestResponse('vlpreco deve ser maior que zero'));
    Exit;
  end;
  AProduto.Insert;
  // cdproduto (foAutoGenerated) já vem preenchido aqui — seção 9.4
  Render(CreatedResponse('/produtos/' + IntToStr(AProduto.cdproduto), AProduto));
end;
DICA
AProduto, em CreateProduto/UpdateProduto, chega pronto via [MVCFromBody] — não é liberado
manualmente com Free no controller, mesmo padrão já usado nos exemplos de [MVCFromBody] dos
capítulos 3 e 12. Quem instancia via GetByPK<T>/SelectRQL<T> dentro do próprio método, por outro
lado, é responsável por liberar — daí o try/finally ao redor de LProduto em GetProdutoById.





OBJECT PASCAL · UPDATEPRODUTO E DELETEPRODUTO
procedure TProdutoController.UpdateProduto(const id: Integer; AProduto: TProduto);
var
  LExistente: TProduto;
begin
  if AProduto.dsproduto.Trim.IsEmpty then
  begin
    Render(BadRequestResponse('dsproduto é obrigatório'));
    Exit;
  end;
  if AProduto.vlpreco <= 0 then
  begin
    Render(BadRequestResponse('vlpreco deve ser maior que zero'));
    Exit;
  end;
  LExistente := TMVCActiveRecord.GetByPK<TProduto>(id, False);
  if not Assigned(LExistente) then
  begin
    Render(NotFoundResponse('Produto não encontrado'));
    Exit;
  end;
  try
    LExistente.dsproduto   := AProduto.dsproduto;
    LExistente.vlpreco     := AProduto.vlpreco;
    LExistente.qtestoque   := AProduto.qtestoque;
    LExistente.cdcategoria := AProduto.cdcategoria;
    LExistente.Update; // RaiseExceptionIfNotFound = True por padrão (seção 9.4)
    Render(OKResponse(LExistente));
  finally
    LExistente.Free;
  end;
end;
procedure TProdutoController.DeleteProduto(const id: Integer);
var
  LProduto: TProduto;
begin
  LProduto := TMVCActiveRecord.GetByPK<TProduto>(id, False);
  if not Assigned(LProduto) then
  begin
    Render(NotFoundResponse('Produto não encontrado'));
    Exit;
  end;
  try
    LProduto.Delete;
    Render(NoContentResponse);




31.6Master-detail na prática: TPedidoController.CreatePedido
TPedido já está declarada nos moldes da seção 13.5: campo itens: TObjectList<TPedidoItem> marcado com
[MVCOwned(TPedidoItem)], e um OnAfterInsert que percorre itens gravando cada TPedidoItem — o hook
dispara depois que a PK autogerada do pedido já foi resolvida (seção 9.5), então cada item já sabe a qual cdpedido
pertence:
Com a cascata de persistência já resolvida do lado da entidade, o trabalho do controller é: validar que cada
cdproduto referenciado existe e tem estoque suficiente, travar o vlunitario de cada item no preço atual do
produto (para não depender do preço mudar entre o pedido e uma eventual reconsulta), somar o vltotal, gravar
tudo numa transação e, na mesma transação, dar baixa no estoque de cada produto.
  finally
    LProduto.Free;
  end;
end;
OBJECT PASCAL · TPEDIDO.ONAFTERINSERT (RECAPITULANDO CAPÍTULOS 9 E 13)
procedure TPedido.OnAfterInsert;
var
  LItem: TPedidoItem;
begin
  inherited;
  for LItem in itens do
  begin
    LItem.cdpedido := cdpedido; // PK do pedido já resolvida neste ponto do ciclo de vida
    LItem.Insert;
  end;
end;
DICA
Este loop manual em OnAfterInsert não usa TMVCActiveRecord.Merge<T> (Capítulo 9, seção 9.7) — e
está certo em não usar: CreatePedido é um endpoint de criação, não existe uma "lista antiga" no banco
pra comparar contra os itens recebidos, então todo item é trivialmente um eaCreate. O padrão com
Merge/Apply (com callback, inclusive) vale a pena quando o endpoint é de atualização de uma entidade
que já tem filhos gravados no banco — a seção 9.7 tem um exemplo completo desse cenário, com múltiplas
listas filhas sincronizadas na mesma transação.





OBJECT PASCAL · TPEDIDOCONTROLLER.CREATEPEDIDO
[MVCPath('/pedidos')]
[MVCRequiresAuthentication]
TPedidoController = class(TMVCController)
public
  [MVCPath]
  [MVCHTTPMethod([httpPOST])]
  [MVCConsumes(TMVCMediaType.APPLICATION_JSON)]
  procedure CreatePedido([MVCFromBody] APedido: TPedido);
end;
procedure TPedidoController.CreatePedido(APedido: TPedido);
var
  LItem: TPedidoItem;
  LProduto: TProduto;
  LProdutosCache: TObjectDictionary<Integer, TProduto>;
  LVlTotal: Currency;
begin
  if (not Assigned(APedido.itens)) or (APedido.itens.Count = 0) then
  begin
    Render(BadRequestResponse('O pedido precisa ter ao menos um item'));
    Exit;
  end;
  LProdutosCache := TObjectDictionary<Integer, TProduto>.Create([doOwnsValues]);
  try
    // 1) valida cada item: produto existe e tem estoque suficiente
    //    (mantém um cache local — o mesmo produto pode aparecer em mais de um item)
    for LItem in APedido.itens do
    begin
      if not LProdutosCache.ContainsKey(LItem.cdproduto) then
      begin
        LProduto := TMVCActiveRecord.GetByPK<TProduto>(LItem.cdproduto, False);
        if not Assigned(LProduto) then
        begin
          Render(BadRequestResponse(Format('Produto %d não encontrado', [LItem.cdproduto])));
          Exit;
        end;
        LProdutosCache.Add(LItem.cdproduto, LProduto);
      end;
      LProduto := LProdutosCache[LItem.cdproduto];
      if LProduto.qtestoque < LItem.qtitem then
      begin
        Render(BadRequestResponse(Format(
          'Estoque insuficiente para o produto %d (disponível: %d, solicitado: %d)',
          [LItem.cdproduto, LProduto.qtestoque, LItem.qtitem])));
        Exit;




      end;
    end;
    // 2) trava vlunitario no preço atual do produto e soma vltotal
    LVlTotal := 0;
    for LItem in APedido.itens do
    begin
      LProduto := LProdutosCache[LItem.cdproduto];
      LItem.vlunitario := LProduto.vlpreco;
      LVlTotal := LVlTotal + (LItem.qtitem * LItem.vlunitario);
    end;
    APedido.vltotal  := LVlTotal;
    APedido.dtpedido := Now;
    APedido.stpedido := 1; // 1 = Aberto
    // 3) grava pedido + itens (cascata via OnAfterInsert) e baixa o estoque,
    //    tudo dentro da mesma transação (padrão da seção 9.7)
    TMVCActiveRecord.CurrentConnection.StartTransaction;
    try
      APedido.Insert;
      for LItem in APedido.itens do
      begin
        LProduto := LProdutosCache[LItem.cdproduto];
        LProduto.qtestoque := LProduto.qtestoque - LItem.qtitem;
        LProduto.Update;
      end;
      TMVCActiveRecord.CurrentConnection.Commit;
    except
      TMVCActiveRecord.CurrentConnection.Rollback;
      raise;
    end;
    Render(CreatedResponse('/pedidos/' + IntToStr(APedido.cdpedido), APedido));
  finally
    LProdutosCache.Free; // doOwnsValues libera cada TProduto em cache junto com o dicionário
  end;
end;




31.7Referência rápida do capítulo
Padrões reaproveitados neste capítulo
GetByPK<T>(id, False) + Assigned + NotFoundResponse — leitura única (seção 3.1 / 9.4).
Count<T>(RQL) + SelectRQL<T>(RQL, MaxRecordCount) — listagem paginada com filtro (seção 10.4).
BadRequestResponse antes de qualquer Insert/Update — validação de negócio explícita (seção 3.4).
[MVCOwned] + OnAfterInsert — cascata de master-detail na criação (seções 9.7 e 13.5).
TMVCActiveRecord.CurrentConnection.StartTransaction/Commit/Rollback — consistência entre gravação do
pedido e baixa de estoque (seção 9.7).
RESUMO DO CAPÍTULO
TProdutoController ficou completo: listagem paginada com filtro opcional traduzido para RQL
(GetProdutos), busca avançada com RQL cru (GetProdutosSearch), leitura única, criação e atualização
com validação de negócio (dsproduto não vazio, vlpreco > 0), e exclusão — todos usando a família
OKResponse/CreatedResponse/NotFoundResponse/BadRequestResponse/NoContentResponse do
capítulo 3.
Count<T>(RQL) conta os registros do filtro sem trazer dados; a mesma string de filtro, com sort/limit
anexados, alimenta SelectRQL<T> para a página pedida.
TPedidoController.CreatePedido mostrou o master-detail de ponta a ponta: validação de estoque por
item, cálculo de vltotal, Insert do pedido cascateando para os itens via [MVCOwned]/OnAfterInsert,
e baixa de estoque de cada produto — tudo dentro de uma única transação com
StartTransaction/Commit/Rollback.
Ficou pendente, deliberadamente fora do escopo: lock explícito de linha para fechar por completo a janela
de corrida na baixa de estoque sob alta concorrência.
No próximo capítulo: os controllers construídos aqui ganham a família completa de atributos [MVCSwagXxx]
(capítulo 15) — descrição, parâmetros, corpo esperado e respostas possíveis de cada rota — até a Loja API
aparecer inteira, testável, na Swagger UI em /api/ajuda, sem precisar manter um swagger.json escrito à mão.
ATENÇÃO
A validação de estoque roda antes de abrir a transação, e a baixa de estoque roda dentro dela — isso fecha
a maior parte da janela de corrida entre duas requisições concorrentes disputando a mesma unidade em
estoque, mas não fecha 100%: entre o SELECT de validação e o UPDATE de baixa, duas transações podem
ler o mesmo qtestoque antes de qualquer uma delas commitar. Resolver isso de vez exige lock explícito de
linha (SELECT ... FOR UPDATE, fora do vocabulário do MVCActiveRecord puro — precisaria de Where<T>
com SQL cru) ou uma constraint CHECK (qtestoque >= 0) no banco como rede de segurança final, que
faria o Update levantar uma violação de constraint em vez de gravar estoque negativo. Para o volume de
concorrência da Loja API isso fica como exercício — vale ter em mente antes de levar este endpoint para um
cenário de alto tráfego.
⚠

PARTE X — PROJETO FINAL
Capítulo 33
Observabilidade e Proteção: o Pipeline de Middlewares
Completo
A Loja API já tem entidades, controllers CRUD, autenticação JWT (Capítulo 30) e documentação Swagger (Capítulo 32). O que
ainda falta é o que separa um protótipo de uma API pronta para produção: o pipeline de middlewares completo, registrado
na ordem certa, cobrindo CORS, arquivos estáticos, observabilidade (analytics/trace), conexão de banco por requisição,
proteção contra abuso (rate limit), compressão, cache condicional (ETag) e um log final de cada requisição atendida. Este
capítulo monta o ConfigureMiddlewares definitivo de LojaAPI.Services.Dm.pas, reaproveitando a ordem
genérica recomendada no Capítulo 4 e os middlewares detalhados nos Capítulos 6 e 8 — nada aqui é novo em termos de
framework, é a peça que faltava para ver tudo funcionando junto.
33.1Retomando o que já está pronto
Antes de escrever uma linha de código novo, vale listar o que a Loja API já registra em ConfigureMiddlewares a
esta altura do livro, porque este capítulo não reescreve esse trabalho — só encaixa as peças que faltam ao redor
dele:
TMVCSwaggerMiddleware (Capítulo 32) — documento OpenAPI e UI do Swagger em /api/ajuda, já configurado
com os dados da Loja API e o esquema de segurança JWT.
Autenticação JWT (Capítulo 30) — middleware de autenticação (embutido ou customizado, conforme a
abordagem escolhida naquele capítulo) validando o token em Authorization: Bearer e populando
AContext.LoggedUser.
Entidades TProdutoDTO, TClienteDTO e TPedidoDTO e os respectivos TProdutoController,
TClienteController, TPedidoController, já registrados em AddControllers.
Nenhum desses três pontos é reescrito aqui — este capítulo só decide onde, na sequência de AddMiddleware, cada
um deles entra, e preenche as lacunas ao redor: CORS, arquivos estáticos gerais, analytics/trace, conexão de banco,
rate limit, compressão, ETag e um log final da requisição.
