procedure TLojaResponseLogMiddleware.OnAfterRouting(AContext: TWebContext; const AHandled: Boolean);
var
  LStartedAt: string;
  LDurationMs: Int64;
begin
  if AContext.Data.TryGetValue('request_started_at', LStartedAt) then
  begin
    LDurationMs := MilliSecondsBetween(Now, StrToDateTime(LStartedAt));
    FLogger.Info(
      Format('%s %s -> %d (%d ms)',
        [AContext.Request.HTTPMethodAsString, AContext.Request.PathInfo,
         AContext.Response.StatusCode, LDurationMs]),
      'RESPONSE'
    );
  end;
end;
end.
